import subprocess
import platform
import time
def task_func(url):
    if platform.system() == "Windows":
        process = subprocess.Popen(["start", url], shell=True)
    elif platform.system() == "Darwin":
        process = subprocess.Popen(["open", url], shell=True)
    else:
        process = subprocess.Popen(["xdg-open", url], shell=True)

    time.sleep(1)
    return process.poll()

