import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    success = True
    message = "All files compressed and moved successfully."
    failed_files = []

    if not os.path.exists(src_folder):
        success = False
        message = "Source folder does not exist."
        return {'success': success, 'message': message, 'failed_files': failed_files}

    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    files = glob(os.path.join(src_folder, '*'))

    for file in files:
        if os.path.isfile(file):
            try:
                subprocess.run(['gzip', file], check=True)
                shutil.move(file + '.gz', dst_folder)
            except Exception as e:
                success = False
                message = f"Failed to compress or move file: {file}"
                failed_files.append(os.path.basename(file))

    return {'success': success, 'message': message, 'failed_files': failed_files}

