import subprocess
import pandas as pd
def task_func(script_path, output_file_path):
    try:
        subprocess.run([script_path], check=True)
    except subprocess.CalledProcessError:
        raise ValueError("Script execution failed")

    try:
        df = pd.read_csv(output_file_path)
        if df.shape[1] != 2:
            raise ValueError("CSV does not contain exactly 2 columns")
    except Exception as e:
        raise ValueError("Invalid CSV file") from e

    ax = df.plot(kind='bar', x=df.columns[0], y=df.columns[1])
    return df, ax

